 "content": "from collections import deque

def transform(grid):
    a=[row[:] for row in grid]; h=len(a); w=len(a[0])
    markers=[(r,c) for r in range(h) for c in range(w) if a[r][c]==1]
    rows={r for r,c in markers}; cols={c for r,c in markers}
    # Marker cross is the row/column shared by the edge markers.
    hr=max(rows) if len(rows)>1 else next(iter(rows))
    vc=max(cols) if len(cols)>1 else next(iter(cols))
    seen=set()
    for r in range(h):
      for c in range(w):
        if a[r][c]!=2 or (r,c) in seen: continue
        q=[(r,c)]; seen.add((r,c)); comp=[]
        while q:
          x,y=q.pop(); comp.append((x,y))
          for nx,ny in ((x+1,y),(x-1,y),(x,y+1),(x,y-1)):
            if 0<=nx<h and 0<=ny<w and a[nx][ny]==2 and (nx,ny) not in seen:
              seen.add((nx,ny)); q.append((nx,ny))
        if any(x==hr or y==vc for x,y in comp):
          for x,y in comp: a[x][y]=1
    for c in range(w): a[hr][c]=1
    for r in range(h): a[r][vc]=1
    return a
"
